<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {LabRun} from '../algorithmLab';
import {money} from '../format';
defineEmits<{open:[string]}>();
const props=defineProps<{run:LabRun;hideOpen?:boolean}>();
const row=computed(()=>props.run.rows[0]),d=computed(()=>row.value?.diagnosis);
const cost=ref(''),quantity=ref(''),sellable=ref('');
function restore(){try{const v=JSON.parse(localStorage.getItem('wangzha-position-study-'+row.value?.security.id)||'{}');cost.value=v.cost??'';quantity.value=v.quantity??'';sellable.value=v.sellable??'';}catch{}}
watch(()=>row.value?.security.id,restore,{immediate:true});
watch([cost,quantity,sellable],()=>{try{localStorage.setItem('wangzha-position-study-'+row.value?.security.id,JSON.stringify({cost:cost.value,quantity:quantity.value,sellable:sellable.value}));}catch{}});
const position=computed(()=>{const p=d.value?.price,c=Number(cost.value),q=Number(quantity.value),s=Number(sellable.value);if(!p||!Number.isFinite(c)||!Number.isInteger(q)||c<=0||q<=0)return undefined;if(!Number.isInteger(s)||s<0||s>q)return {error:'可卖股数须为0至持仓股数之间的整数。'};return {pnl:(p-c)*q,pct:(p/c-1)*100,sellable:s};});
</script>
<template><section v-if="row" class="stock-diagnosis panel"><div class="lab-section-title"><div><span class="lab-step">个股研究简报</span><h2>{{row.security.name}} · {{d?.summary||'请使用完成日线运行个股诊断'}}</h2></div><span class="badge">{{d?.as_of||'日线输入不足'}}</span></div><p class="tiny muted">回答趋势、位置和风险；下方算法检查是证据，不能直接替代持仓决策。</p><div class="diagnosis-grid"><div v-for="m in d?.metrics" :key="m.label"><span>{{m.label}}</span><strong>{{m.value}}</strong></div></div><p v-for="c in d?.conditions" :key="c">{{c}}</p><p class="tiny muted" v-for="v in d?.limitations" :key="v">{{v}}</p><details v-if="d?.status==='READY'"><summary>结合我的持仓核对（仅本机研究记录）</summary><div class="batch-filters"><label>持仓成本<input type="number" min="0" step="0.01" v-model="cost"></label><label>持仓股数<input type="number" min="0" step="100" v-model="quantity"></label><label>当前可卖股数<input type="number" min="0" step="100" v-model="sellable"></label></div><p v-if="position?.error" class="error-line">{{position.error}}</p><p v-else-if="position">按这批日线收盘估算浮动盈亏 {{money(position.pnl)}} 元（{{money(position.pct)}}%），未计费用。{{position.sellable===0?'当前无可卖底仓，不具备先卖后买的做T条件。':'有可卖底仓仍需实时价差、费用和执行约束；当前日线诊断不足以给出做T买卖点。'}}补仓会增加敞口，应先填写并核对自己的风险预算，不因浮亏自动补仓。</p><p v-else class="tiny muted">填写成本、股数和可卖数量后，展示基于本批价格的持仓检查，不生成订单。</p></details><div v-if="row.news_evidence?.length" class="lab-news-evidence"><strong>近期关联公告线索</strong><article v-for="n in row.news_evidence" :key="n.id"><span class="badge">{{n.direction}}</span> <a :href="n.url" target="_blank" rel="noopener noreferrer">{{n.title}} ↗</a><p class="tiny muted">{{n.reason}} · {{n.verification}}</p></article></div><p v-else class="tiny muted">本批缓存未提供近期关联公告，不代表公司没有公告；请到K线页公司资料核对。</p><button v-if="!hideOpen" class="text-button" @click="$emit('open',row.security.id)">打开完整K线与公司资料 →</button></section></template>
